do $$ declare t text; begin foreach t in array array['socios','transportadoras','recebimentos_transportadoras','motoboys','pagamentos_motoboys','custos','vales_extravios','fechamentos','repasses_socios','configuracoes','historico_alteracoes'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists "autenticados_leem" on public.%I',t); execute format('drop policy if exists "autenticados_inserem" on public.%I',t); execute format('drop policy if exists "autenticados_atualizam" on public.%I',t); execute format('create policy "autenticados_leem" on public.%I for select to authenticated using (true)',t); execute format('create policy "autenticados_inserem" on public.%I for insert to authenticated with check (auth.uid() is not null)',t); execute format('create policy "autenticados_atualizam" on public.%I for update to authenticated using (true) with check (auth.uid() is not null)',t); end loop; end $$;
-- Não há política DELETE: registros financeiros devem ser cancelados, nunca apagados pelo navegador.

